import { shell } from '../lib/shell.js'
import type { Candidate, DiscoveryResult } from './types.js'

interface SpecCoverageReport {
  scenarios: {
    total: number
    covered: number
    uncovered: number
    coveragePercent: number
  }
  uncoveredScenarioIds: string[]
}

export async function discoverIntegrationGaps(targetDir: string): Promise<DiscoveryResult> {
  const result = shell(
    'yarn mercato test:integration:spec-coverage --json 2>/dev/null',
    { cwd: targetDir, timeout: 60_000 },
  )

  if (!result.success || !result.stdout) {
    return {
      candidates: [],
      source: 'integration_gap',
      discoveredAt: new Date().toISOString(),
    }
  }

  let report: SpecCoverageReport
  try {
    report = JSON.parse(result.stdout)
  } catch {
    return {
      candidates: [],
      source: 'integration_gap',
      discoveredAt: new Date().toISOString(),
    }
  }

  const candidates: Candidate[] = report.uncoveredScenarioIds.map((scenarioId) => ({
    id: `TESTSIG-integration-scenario-${scenarioId.toLowerCase()}`,
    source: 'integration_gap' as const,
    title: `tests: add integration test for ${scenarioId}`,
    description: `Scenario ${scenarioId} has a .md definition but no matching .spec.ts test file.`,
    suggestedLane: 'tests' as const,
    suggestedRisk: 'green' as const,
    expectedClasses: ['tests'],
    expectedPoints: 3,
    confidence: 'high',
    metadata: { scenarioId },
  }))

  return {
    candidates,
    source: 'integration_gap',
    discoveredAt: new Date().toISOString(),
  }
}
